
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_20_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_20", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.220889519683391e+00, -5.118122952026099e+00, -4.973936800092577e+00, -4.773774818885496e+00, -4.499997736940225e+00, -4.133011521301551e+00, -3.653696150542559e+00, -3.046184432611546e+00, -2.302480490672146e+00, -1.481715814651312e+00, -8.524626374888029e-01, -6.255330490555232e-01, -6.332596299101915e-01, -5.454996509892512e-01, -3.632397993247025e-01, -1.894734861425194e-01, -8.002010722504534e-02, -2.617986279012373e-02, -5.603325431740878e-03, -6.298662102888886e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


